SELECT m.CSNAME AS `股票名称`, m.COMB_SYMBOL AS `股票代码`, c.F001D AS `财政周期结束日期`, c.F003V AS `报表种类`, c.F004N AS `财政期间长度(天数)`, ROUND(c.F032N / 100, 3) AS `净利润(亿美元)`, CONCAT(ROUND(c.F032N / 100, 3), ' 亿美元') AS `净利润(亿)`, c.F005V AS `货币类型` FROM AMERICAN_STOCK_MAIN m JOIN VIEW_COM3103_CUM c ON m.FIU_ID = c.FIU_ID WHERE m.COMB_SYMBOL = 'AAPL.US' AND c.F056N = 2025 AND c.F003V = 'FY' AND c.F032N IS NOT NULL ORDER BY c.F001D DESC LIMIT 1;
